  shift; a=(); for kv in "$@"; do a+=(--data-urlencode "$kv"); done; c=$(crumb)
  code=$(cu -o /tmp/resp -D /tmp/hdr -w '%{http_code}' -H "$c" -X POST "${a[@]}" "$J/job/$JOB/buildWithParameters")
